// Row 263 unit lane — the estate render-and-deliver stage (src/estate/deliver.ts + ledger.ts).
//
// NO docker, NO network, NO real home: every test pins process.env.HOME at a mkdtemp sandbox and
// VERIFIES the resolved path took effect before anything writes (rule E7 — the incident it encodes
// destroyed a user's state.json once). Secrets here are sandbox material generated by the code under
// test or planted as fixed dummies; none is ever printed (R4).
//
// What each describe pins, against masterplan/08_s6b_estate_delivery_spec.md:
//   complete set        -> §2.5/§2.6 fifteen-artefact arithmetic, per-stack scope (D-262-2),
//                          §4.6 secret shapes, R-262-2 no-rotation, the forbidden
//                          ARTEFACT_MISSING->BIND_SOURCE_MISSING half-delivery state shown
//                          reachable by a compose-only delivery and UNREACHABLE by this stage
//   idempotence         -> R-262-1 content-addressed no-write (mtimes+hashes frozen across a re-run)
//   failure posture     -> §4.1 closed codes, refuse-before-bytes, rollback from captured priors,
//                          own-.tmp-only teardown (E13), skipped-stays-skipped (§1.5)
//   state walk          -> §1.5 absent->...->configured through one kit, so bring-up's existing
//                          configured->healthy edge is reached untouched
//   residue             -> R-262-3 report-not-prune
//   run-as-main         -> D-262-4 (the trap: bundled renderer + argv-shape predicate = exit 1 mid-install)
//   fence               -> R-262/E + spec §5.3 discriminators D-A/D-B/D-C under the harness recipe
//
// Collected by the package's declared command (`bun test` from packages/setup) — rule E14.

import { describe, it, expect } from "bun:test"
import {
  chmodSync,
  existsSync,
  lstatSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
  readdirSync,
  rmSync,
  statSync,
  writeFileSync,
} from "node:fs"
import { createHash } from "node:crypto"
import { tmpdir } from "node:os"
import { pathToFileURL } from "node:url"
import { join } from "node:path"
import { OUTCOME } from "../src/outcomes.ts"
import { STATES } from "../src/constants.ts"
import { defaultState, type StateFile } from "../src/state.ts"
import { validateLock } from "../src/lockfile.ts"
import { createStepKit } from "../src/stepkit.ts"
import { homeDir, isCompiledBinary } from "../src/paths.ts"
import { renderAll, applyRenderedFiles } from "../src/composefiles/index.ts"
import { SECRET_INVENTORY } from "../src/composefiles/shared.ts"
import { checkPreconditions, firecrawlPlan, searxngPlan } from "../src/stacklib.ts"
import { deliverEstate, fenceApplyRendered } from "../src/estate/deliver.ts"
import { DELIVER_CODES, estateDeliveryFile, readEstateDeliveryRecords } from "../src/estate/ledger.ts"

const LOCK = (() => {
  const r = validateLock(JSON.parse(readFileSync(join(import.meta.dir, "..", "tools.lock.json"), "utf8")))
  if (!r.ok) throw new Error(`r263 test lock invalid: ${r.error}`)
  return r.lock
})()

const sha = (text: string): string => createHash("sha256").update(text, "utf8").digest("hex")
const modeOf = (p: string): number => statSync(p).mode & 0o777

/** E7-safe sandbox: pin HOME, VERIFY the resolved path before the body may write, restore after. */
function withHome<T>(fn: (home: string) => T): T {
  const saved = process.env.HOME
  const home = mkdtempSync(join(tmpdir(), "r263-"))
  process.env.HOME = home
  if (homeDir() !== home) {
    process.env.HOME = saved
    throw new Error(`E7: HOME pin did not take effect (homeDir()=${homeDir()})`)
  }
  try {
    return fn(home)
  } finally {
    if (saved === undefined) delete process.env.HOME
    else process.env.HOME = saved
    rmSync(home, { recursive: true, force: true })
  }
}

const toolsRootOf = (home: string): string => join(home, ".swarm", "tools")

/** Valid dummy secrets (fixed values, never rotated semantics need randomness): 64 hex chars, 0600. */
function seedSecret(home: string, component: "searxng" | "firecrawl", slot: string, content = "f".repeat(64), mode = 0o600): string {
  const dir = join(toolsRootOf(home), component, "secrets")
  mkdirSync(dir, { recursive: true, mode: 0o700 })
  const p = join(dir, slot)
  writeFileSync(p, content, { mode })
  chmodSync(p, mode)
  return p
}

function seedRequiredSecrets(home: string, components: readonly ("searxng" | "firecrawl")[]): void {
  for (const c of components) for (const s of SECRET_INVENTORY[c]) if (s.required) seedSecret(home, c, s.name)
}

function kitFor(component: "searxng" | "firecrawl", state: StateFile) {
  return createStepKit({ componentId: component, lock: LOCK, state, dryRun: false })
}

const RENDERED_REL = {
  searxng: ["searxng/compose/searxng.yml", "searxng/settings.yml", "searxng/searxng.env"],
  firecrawl: [
    "firecrawl/compose/firecrawl.yml",
    "firecrawl/nginx/default.conf.template",
    "firecrawl/squid/squid.conf",
    "firecrawl/compose/bin/fc-env.sh",
    "firecrawl/compose/bin/redis-start.sh",
    "firecrawl/compose/bin/nuq-postgres-start.sh",
    "firecrawl/compose/bin/fc-nginx-env.envsh",
  ],
}
const EXPECTED_MODE: Record<string, number> = {
  "searxng/compose/searxng.yml": 0o644,
  "searxng/settings.yml": 0o600,
  "searxng/searxng.env": 0o600,
  "firecrawl/compose/firecrawl.yml": 0o644,
  "firecrawl/nginx/default.conf.template": 0o600,
  "firecrawl/squid/squid.conf": 0o644,
  "firecrawl/compose/bin/fc-env.sh": 0o600,
  "firecrawl/compose/bin/redis-start.sh": 0o600,
  "firecrawl/compose/bin/nuq-postgres-start.sh": 0o600,
  "firecrawl/compose/bin/fc-nginx-env.envsh": 0o700,
}

function listFilesUnder(dir: string): string[] {
  if (!existsSync(dir)) return []
  const out: string[] = []
  for (const name of readdirSync(dir)) {
    const abs = join(dir, name)
    if (statSync(abs).isDirectory()) out.push(...listFilesUnder(abs))
    else out.push(abs)
  }
  return out
}

describe("r263 complete artefact set (spec §2.5/§2.6, D-262-2)", () => {
  it("searxng install delivers exactly its 3 tagged artefacts + keeps its 1 present secret; no firecrawl tree", () => {
    withHome((home) => {
      seedRequiredSecrets(home, ["searxng"])
      const before = sha(readFileSync(join(toolsRootOf(home), "searxng", "secrets", "secret_key"), "utf8"))
      const state = defaultState(LOCK.version)
      const res = deliverEstate({ kit: kitFor("searxng", state), home })
      expect(res.token).toBe(OUTCOME.OK)
      for (const rel of RENDERED_REL.searxng) {
        expect(existsSync(join(toolsRootOf(home), rel))).toBe(true)
        expect(modeOf(join(toolsRootOf(home), rel))).toBe(EXPECTED_MODE[rel])
      }
      expect(existsSync(join(toolsRootOf(home), "firecrawl"))).toBe(false) // per-stack WRITE scope
      expect(sha(readFileSync(join(toolsRootOf(home), "searxng", "secrets", "secret_key"), "utf8"))).toBe(before) // R-262-2
      expect(state.components.searxng.state).toBe(STATES.CONFIGURED)
      const rows = readEstateDeliveryRecords(estateDeliveryFile()).filter((r): r is NonNullable<typeof r> => r !== null)
      expect(rows.map((r) => r.action)).toEqual(["attempt", "delivered"])
      expect(rows[0]?.program.compiled).toBe(false) // source posture under bun test — D-B
      const delivered = rows[1]
      expect(delivered?.artefacts.length).toBe(3)
      for (const row of delivered?.artefacts ?? [])
        expect(sha(readFileSync(row.absPath, "utf8"))).toBe(row.sha256) // D-A hash binds bytes
    })
  })

  it("firecrawl install delivers its 7 tagged artefacts (fc-nginx-env.envsh at 0700) + 4 secrets; no searxng tree", () => {
    withHome((home) => {
      seedRequiredSecrets(home, ["firecrawl"])
      const state = defaultState(LOCK.version)
      const res = deliverEstate({ kit: kitFor("firecrawl", state), home })
      expect(res.token).toBe(OUTCOME.OK)
      for (const rel of RENDERED_REL.firecrawl) {
        expect(existsSync(join(toolsRootOf(home), rel))).toBe(true)
        expect(modeOf(join(toolsRootOf(home), rel))).toBe(EXPECTED_MODE[rel])
      }
      expect(existsSync(join(toolsRootOf(home), "searxng"))).toBe(false)
      expect(state.components.firecrawl.state).toBe(STATES.CONFIGURED)
    })
  })

  it("union across both installs equals the fifteen-artefact complete set; cache/logs stay absent", () => {
    withHome((home) => {
      seedRequiredSecrets(home, ["searxng", "firecrawl"])
      const state = defaultState(LOCK.version)
      expect(deliverEstate({ kit: kitFor("searxng", state), home }).token).toBe(OUTCOME.OK)
      expect(deliverEstate({ kit: kitFor("firecrawl", state), home }).token).toBe(OUTCOME.OK)
      const files = listFilesUnder(toolsRootOf(home))
      expect(files.length).toBe(15) // 10 rendered + 5 required secrets (spec §2.6)
      expect(existsSync(join(toolsRootOf(home), "searxng", "cache"))).toBe(false) // bring-up creates those; bring-up is not running
      expect(existsSync(join(toolsRootOf(home), "firecrawl", "logs"))).toBe(false)
    })
  })

  it("absent required secrets are GENERATED at §4.6 shapes and never rotated by a later run", () => {
    withHome((home) => {
      const state = defaultState(LOCK.version)
      expect(deliverEstate({ kit: kitFor("searxng", state), home }).token).toBe(OUTCOME.OK)
      expect(deliverEstate({ kit: kitFor("firecrawl", state), home }).token).toBe(OUTCOME.OK)
      const read = (c: string, s: string): string => readFileSync(join(toolsRootOf(home), c, "secrets", s), "utf8").trim()
      expect(read("searxng", "secret_key")).toMatch(/^[0-9a-f]{64}$/) // openssl rand -hex 32
      expect(read("firecrawl", "proxy_token")).toMatch(/^[A-Za-z0-9_-]{43}$/) // 32B base64url unpadded
      expect(read("firecrawl", "postgres_password")).toMatch(/^[A-Za-z0-9_-]{64}$/) // 48B, >=32 floor
      expect(read("firecrawl", "bull_auth_key")).toMatch(/^[A-Za-z0-9_-]{43}$/)
      expect(read("firecrawl", "redis_auth")).toMatch(/^[0-9a-f]{64}$/) // U-4 ON
      for (const [c, s] of [["searxng", "secret_key"], ["firecrawl", "proxy_token"], ["firecrawl", "postgres_password"], ["firecrawl", "bull_auth_key"], ["firecrawl", "redis_auth"]] as const)
        expect(modeOf(join(toolsRootOf(home), c, "secrets", s))).toBe(0o600)
      const secretRel = ["searxng/secrets/secret_key", "firecrawl/secrets/proxy_token", "firecrawl/secrets/postgres_password", "firecrawl/secrets/bull_auth_key", "firecrawl/secrets/redis_auth"]
      const hashes = secretRel.map((p) => sha(readFileSync(join(toolsRootOf(home), p), "utf8")))
      expect(deliverEstate({ kit: kitFor("searxng", state), home }).token).toBe(OUTCOME.OK)
      expect(deliverEstate({ kit: kitFor("firecrawl", state), home }).token).toBe(OUTCOME.OK)
      const after = secretRel.map((p) => sha(readFileSync(join(toolsRootOf(home), p), "utf8")))
      expect(after).toEqual(hashes) // R-262-2: a live secret is never rotated
      const rows = readEstateDeliveryRecords(estateDeliveryFile()).filter((r): r is NonNullable<typeof r> => r !== null)
      const lastFirecrawl = [...rows].reverse().find((r) => r.stack === "firecrawl" && r.action !== "attempt")
      expect(lastFirecrawl?.secrets.every((s) => s.action === "present")).toBe(true)
    })
  })

  it("present-but-invalid secrets refuse with named SECRET_MISSING-mirror rows and ZERO bytes touched", () => {
    withHome((home) => {
      seedSecret(home, "searxng", "secret_key", "") // empty == unset (P-8 placeholder class)
      const state = defaultState(LOCK.version)
      const res = deliverEstate({ kit: kitFor("searxng", state), home })
      expect(res.token).toBe(OUTCOME.FAILED)
      expect(res.message).toContain("[DELIVER_SECRET_INVALID]")
      expect(res.message).toContain("SECRET_MISSING mirror")
      expect(res.message.split("\n")[0]).toContain("secret_key") // §4.3: code AND path in line one
      expect(existsSync(join(toolsRootOf(home), "searxng", "compose", "searxng.yml"))).toBe(false)
      const rows = readEstateDeliveryRecords(estateDeliveryFile()).filter((r): r is NonNullable<typeof r> => r !== null)
      expect(rows.at(-1)?.code).toBe("DELIVER_SECRET_INVALID")
      expect(rows.at(-1)?.secrets[0]?.action).toBe("refused")
    })
    withHome((home) => {
      seedSecret(home, "firecrawl", "proxy_token", "x".repeat(64), 0o640) // group-readable
      const res = deliverEstate({ kit: kitFor("firecrawl", defaultState(LOCK.version)), home })
      expect(res.token).toBe(OUTCOME.FAILED)
      expect(res.message).toContain("group/other bits set")
      expect(existsSync(join(toolsRootOf(home), "firecrawl", "compose", "firecrawl.yml"))).toBe(false)
    })
  })

  it("the forbidden state is real for a compose-only delivery and unreachable for this stage (E4 pair)", () => {
    withHome((home) => {
      // Arm 1 — what a half-deliverer produces (the state the user decision forbids):
      seedRequiredSecrets(home, ["searxng"])
      const full = renderAll(LOCK, { home, secrets: { searxng: { secret_key: "generated" }, firecrawl: { proxy_token: "generated", postgres_password: "generated", bull_auth_key: "generated", redis_auth: "generated" } } })
      expect(full.ok).toBe(true)
      applyRenderedFiles({ ...full, files: full.files.filter((f) => f.relPath.endsWith("compose/searxng.yml")) }, toolsRootOf(home))
      const halfState = defaultState(LOCK.version)
      halfState.components.runtime.state = STATES.HEALTHY
      halfState.components.searxng.state = STATES.CONFIGURED
      const halfGaps = checkPreconditions(searxngPlan(home), halfState, home).gaps
      expect(halfGaps.filter((g) => g.code === "BIND_SOURCE_MISSING").length).toBe(2) // settings.yml + searxng.env — ARTEFACT_MISSING converted, exactly as predicted
      // Arm 2 — this stage: after delivery the SAME instrument reports ZERO artefact-class gaps.
      const state = defaultState(LOCK.version)
      state.components.runtime.state = STATES.HEALTHY
      expect(deliverEstate({ kit: kitFor("searxng", state), home }).token).toBe(OUTCOME.OK)
      const gaps = checkPreconditions(searxngPlan(home), state, home).gaps
      expect(gaps.filter((g) => ["ARTEFACT_MISSING", "BIND_SOURCE_MISSING", "SECRET_MISSING", "BIND_SOURCE_OUTSIDE_WHITELIST"].includes(g.code))).toEqual([])
    })
  })
})

describe("r263 idempotence (R-262-1)", () => {
  it("a second run writes nothing when bytes match: mtimes AND hashes frozen", () => {
    withHome((home) => {
      const state = defaultState(LOCK.version)
      expect(deliverEstate({ kit: kitFor("searxng", state), home }).token).toBe(OUTCOME.OK)
      const targets = [...RENDERED_REL.searxng.map((r) => join(toolsRootOf(home), r)), join(toolsRootOf(home), "searxng", "secrets", "secret_key")]
      const snap = targets.map((p) => ({ p, mtime: statSync(p).mtimeMs, sha: sha(readFileSync(p, "utf8")), mode: modeOf(p) }))
      Bun.sleepSync(120) // let the clock move synchronously so any rewrite would show (async would outlive withHome's restore)
      const again = deliverEstate({ kit: kitFor("searxng", state), home })
      expect(again.token).toBe(OUTCOME.OK)
      for (const s of snap) {
        expect(modeOf(s.p)).toBe(s.mode)
        expect(statSync(s.p).mtimeMs).toBe(s.mtime) // find -newer would report nothing
        expect(sha(readFileSync(s.p, "utf8"))).toBe(s.sha)
      }
      const rows = readEstateDeliveryRecords(estateDeliveryFile()).filter((r): r is NonNullable<typeof r> => r !== null)
      const outcome = rows.filter((r) => r.action !== "attempt")
      expect(outcome.map((r) => r.action)).toEqual(["delivered", "unchanged"])
      expect(outcome[1]?.artefacts.every((a) => a.action === "unchanged")).toBe(true)
    })
  })
})

describe("r263 failure posture (§4.1 taxonomy, §4.2 rollback)", () => {
  it("unwritable ancestor refuses BEFORE touching bytes with DELIVER_TARGET_UNWRITABLE", () => {
    withHome((home) => {
      seedRequiredSecrets(home, ["searxng"])
      const state = defaultState(LOCK.version)
      expect(deliverEstate({ kit: kitFor("searxng", state), home }).token).toBe(OUTCOME.OK)
      const composeDir = join(toolsRootOf(home), "searxng", "compose")
      const priorYml = join(composeDir, "searxng.yml")
      const priorMtime = statSync(priorYml).mtimeMs
      chmodSync(composeDir, 0o500) // r-x: owner write bit clear
      try {
        const res = deliverEstate({ kit: kitFor("searxng", defaultState(LOCK.version)), home })
        expect(res.token).toBe(OUTCOME.FAILED)
        expect(res.message).toContain("[DELIVER_TARGET_UNWRITABLE]")
        expect(res.message.split("\n")[0]).toContain(composeDir) // path in line one (§4.3)
        expect(statSync(priorYml).mtimeMs).toBe(priorMtime) // refusal changed nothing
      } finally {
        chmodSync(composeDir, 0o700)
      }
    })
  })

  it("mid-pass write failure: prior bytes restored, creations removed, foreign .tmp-* survives (E13)", () => {
    withHome((home) => {
      seedRequiredSecrets(home, ["searxng"])
      const compose = join(toolsRootOf(home), "searxng", "compose", "searxng.yml")
      mkdirSync(join(toolsRootOf(home), "searxng", "compose"), { recursive: true, mode: 0o700 })
      writeFileSync(compose, "OLD PLANTED BYTES\n", { mode: 0o644 })
      const foreignTmp = join(toolsRootOf(home), "searxng", "compose", ".tmp-foreign-not-mine")
      writeFileSync(foreignTmp, "someone else's", { mode: 0o600 })
      const res = deliverEstate({
        kit: kitFor("searxng", defaultState(LOCK.version)),
        home,
        disturbWrite: (absPath) => {
          if (absPath.endsWith("settings.yml")) throw new Error("simulated ENOSPC between writes")
        },
      })
      expect(res.token).toBe(OUTCOME.FAILED)
      expect(res.message).toContain("[DELIVER_WRITE_FAILED]")
      expect(readFileSync(compose, "utf8")).toBe("OLD PLANTED BYTES\n") // captured prior restored
      expect(existsSync(join(toolsRootOf(home), "searxng", "searxng.env"))).toBe(false) // created-in-pass undone
      expect(existsSync(foreignTmp)).toBe(true) // never swept (attribution by deletion forbidden)
      const rows = readEstateDeliveryRecords(estateDeliveryFile()).filter((r): r is NonNullable<typeof r> => r !== null)
      const rb = rows.at(-1)
      expect(rb?.action).toBe("rolled-back")
      expect(rb?.code).toBe("DELIVER_WRITE_FAILED")
      expect(rb?.rolledBack).toContain(compose)
    })
  })

  it("verify mismatch after commit rolls back too, naming DELIVER_VERIFY_MISMATCH", () => {
    withHome((home) => {
      seedRequiredSecrets(home, ["searxng"])
      const compose = join(toolsRootOf(home), "searxng", "compose", "searxng.yml")
      mkdirSync(join(toolsRootOf(home), "searxng", "compose"), { recursive: true, mode: 0o700 })
      writeFileSync(compose, "PRIOR\n", { mode: 0o644 })
      const res = deliverEstate({
        kit: kitFor("searxng", defaultState(LOCK.version)),
        home,
        disturbWrite: (absPath) => {
          if (absPath.endsWith("searxng.env")) writeFileSync(absPath, readFileSync(absPath, "utf8") + "CORRUPTED", { mode: 0o600 })
        },
      })
      expect(res.token).toBe(OUTCOME.FAILED)
      expect(res.message).toContain("[DELIVER_VERIFY_MISMATCH]")
      expect(readFileSync(compose, "utf8")).toBe("PRIOR\n")
      expect(existsSync(join(toolsRootOf(home), "searxng", "searxng.env"))).toBe(false)
      const rows = readEstateDeliveryRecords(estateDeliveryFile()).filter((r): r is NonNullable<typeof r> => r !== null)
      expect(rows.at(-1)?.code).toBe("DELIVER_VERIFY_MISMATCH")
    })
  })

  it("skipped stays skipped: SKIPPED token, no walk, no writes (§1.5)", () => {
    withHome((home) => {
      const state = defaultState(LOCK.version)
      state.components.searxng.state = STATES.SKIPPED
      const res = deliverEstate({ kit: kitFor("searxng", state), home })
      expect(res.token).toBe(OUTCOME.SKIPPED)
      expect(res.message).toContain("[DELIVER_SKIPPED_COMPONENT]")
      expect(existsSync(toolsRootOf(home))).toBe(false)
      expect(state.components.searxng.state).toBe(STATES.SKIPPED) // transitioned nothing
    })
  })

  it("occupied target path refuses pre-bytes instead of throwing (unreadable existing target)", () => {
    withHome((home) => {
      seedRequiredSecrets(home, ["searxng"])
      mkdirSync(join(toolsRootOf(home), "searxng", "settings.yml"), { recursive: true }) // a DIRECTORY squatting the target
      const res = deliverEstate({ kit: kitFor("searxng", defaultState(LOCK.version)), home })
      expect(res.token).toBe(OUTCOME.FAILED)
      expect(res.message).toContain("[DELIVER_TARGET_UNWRITABLE]")
      expect(existsSync(join(toolsRootOf(home), "searxng", "compose", "searxng.yml"))).toBe(false)
    })
  })

  it("configured carries the install manifest: delivered paths + lock version", () => {
    withHome((home) => {
      const state = defaultState(LOCK.version)
      expect(deliverEstate({ kit: kitFor("searxng", state), home }).token).toBe(OUTCOME.OK)
      const entry = state.components.searxng
      expect(entry.state).toBe(STATES.CONFIGURED)
      expect(entry.version).toBe(LOCK.version)
      expect(entry.paths?.length).toBe(4) // 3 artefacts + 1 secret
      expect(entry.paths?.every((p) => p.startsWith(toolsRootOf(home)))).toBe(true)
    })
  })
})

describe("r263 residue (R-262-3)", () => {
  it("a stale sibling the render no longer emits is REPORTED in the ledger and left in place", () => {
    withHome((home) => {
      seedRequiredSecrets(home, ["searxng"])
      const stale = join(toolsRootOf(home), "searxng", "compose", "bin", "old-wrap.sh")
      mkdirSync(join(toolsRootOf(home), "searxng", "compose", "bin"), { recursive: true })
      writeFileSync(stale, "# superseded artefact — informative, not prunable\n", { mode: 0o600 })
      const state = defaultState(LOCK.version)
      expect(deliverEstate({ kit: kitFor("searxng", state), home }).token).toBe(OUTCOME.OK)
      const rows = readEstateDeliveryRecords(estateDeliveryFile()).filter((r): r is NonNullable<typeof r> => r !== null)
      expect(rows.at(-1)?.residue).toContain(stale)
      expect(existsSync(stale)).toBe(true) // reported, never deleted (R5/E13)
    })
  })
})

describe("r263 run-as-main regression (D-262-4)", () => {
  const childSource = (extraArgs: string[]): string => `
    process.argv[1] = "/$bunfs/root/swarm-setup"
    const mod = ${JSON.stringify(pathToFileURL(join(import.meta.dir, "..", "src", "composefiles", "index.ts")).href)}
    await import(mod)
    console.log("ALIVE_NO_CLI_RUN")
    void ${JSON.stringify(extraArgs)}
  `
  function runChild(args: string[]): { exitCode: number; stdout: string; stderr: string } {
    const dir = mkdtempSync(join(tmpdir(), "r263-child-"))
    const file = join(dir, "child.mjs")
    try {
      writeFileSync(file, childSource(args))
      const r = Bun.spawnSync([process.execPath, file, ...args], { stdout: "pipe", stderr: "pipe" })
      return { exitCode: r.exitCode ?? -1, stdout: r.stdout.toString(), stderr: r.stderr.toString() }
    } finally {
      rmSync(dir, { recursive: true, force: true })
    }
  }

  it("importing the renderer under compiled-shaped argv does NOT run the CLI (status posture)", () => {
    const r = runChild([])
    expect(r.stdout).toContain("ALIVE_NO_CLI_RUN")
    expect(r.stdout).not.toContain("RESULT") // old predicate: runCli([]) -> verb "status" -> RESULT OK + exit before ALIVE
    expect(r.exitCode).toBe(0)
  })

  it("importing under compiled-shaped argv with install args does NOT exit 1 mid-install (the D-262-4 trap)", () => {
    const r = runChild(["install", "searxng"])
    expect(r.stdout).toContain("ALIVE_NO_CLI_RUN")
    expect(r.stdout).not.toContain("RESULT") // old predicate: unknown verb -> RESULT FAILED + process.exit(1)
    expect(r.exitCode).toBe(0)
  })
})

describe("r263 harness fence (R-262/E; spec §5.3 D-A/D-B/D-C)", () => {
  it("fenceApplyRendered records intent-before-bytes, binds hashes, and can never claim compiled=true", () => {
    withHome((home) => {
      expect(isCompiledBinary()).toBe(false) // mechanical reason the harness cannot set the flag: repo source + local bun
      const secrets = { searxng: {} as Record<string, "generated">, firecrawl: {} as Record<string, "generated"> }
      for (const c of ["searxng", "firecrawl"] as const) for (const s of SECRET_INVENTORY[c]) if (s.required) secrets[c][s.name] = "generated"
      const rendered = renderAll(LOCK, { home, secrets })
      expect(rendered.ok).toBe(true)
      const out = fenceApplyRendered({
        lock: LOCK,
        home,
        rendered,
        root: toolsRootOf(home),
        entryTokens: ["(harness)", "test/live_smoke.ts", "R93_PHASE=bringup"],
        secretRows: [{ component: "firecrawl", slot: "proxy_token", action: "created", mode: 0o600 }],
      })
      expect(out.applied.length).toBe(10)
      const rows = readEstateDeliveryRecords(estateDeliveryFile()).filter((r): r is NonNullable<typeof r> => r !== null)
      expect(rows.length).toBe(4) // attempt x2 precede, delivered x2 follow
      expect(rows.map((r) => `${r.stack}:${r.action}`)).toEqual(["searxng:attempt", "firecrawl:attempt", "searxng:delivered", "firecrawl:delivered"])
      for (const r of rows) expect(r.program.compiled).toBe(false) // D-B: unsettable under this recipe
      const attemptTs = Math.min(...rows.filter((r) => r.action === "attempt").map((r) => Date.parse(r.ts)))
      for (const rel of [...RENDERED_REL.searxng, ...RENDERED_REL.firecrawl]) {
        const abs = join(toolsRootOf(home), rel)
        expect(lstatSync(abs).birthtimeMs).toBeGreaterThanOrEqual(attemptTs - 1000) // D-C intent precedes bytes (ts granularity slack)
      }
      const bound = new Map(rows.filter((r) => r.action === "delivered").flatMap((r) => r.artefacts.map((a) => [a.relPath, a.sha256])))
      for (const [rel, digest] of bound) expect(sha(readFileSync(join(toolsRootOf(home), rel), "utf8"))).toBe(digest) // D-A
    })
  })

  it("the refusal-code set stays the frozen eight (§4.1: widening needs a controller ruling, not a commit)", () => {
    expect([...DELIVER_CODES].sort()).toEqual(
      [
        "DELIVER_LEDGER_UNWRITABLE",
        "DELIVER_LINT_REFUSED",
        "DELIVER_RENDER_REFUSED",
        "DELIVER_SECRET_INVALID",
        "DELIVER_SKIPPED_COMPONENT",
        "DELIVER_TARGET_UNWRITABLE",
        "DELIVER_VERIFY_MISMATCH",
        "DELIVER_WRITE_FAILED",
      ].sort(),
    )
  })
})
